[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "revenue-analysis-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "revenue-analysis-surface",
      "path": "/",
      "value": {
        "revenue_breakdown": [
          {
            "quarter": "Q1 2023",
            "software": "$45",
            "hardware": "$30",
            "services": "$20",
            "total": "$95"
          },
          {
            "quarter": "Q2 2023",
            "software": "$48",
            "hardware": "$28",
            "services": "$22",
            "total": "$98"
          },
          {
            "quarter": "Q3 2023",
            "software": "$52",
            "hardware": "$35",
            "services": "$25",
            "total": "$112"
          },
          {
            "quarter": "Q4 2023",
            "software": "$60",
            "hardware": "$40",
            "services": "$30",
            "total": "$130"
          }
        ],
        "growth_analysis": [
          {
            "period": "Q1 2023",
            "revenue": "$95k",
            "growth": "-"
          },
          {
            "period": "Q2 2023",
            "revenue": "$98k",
            "growth": "+$3k"
          },
          {
            "period": "Q3 2023",
            "revenue": "$112k",
            "growth": "+$14k"
          },
          {
            "period": "Q4 2023",
            "revenue": "$130k",
            "growth": "+$18k"
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "revenue-analysis-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium"
          },
          "children": [
            "title",
            "assumptions_card",
            "summary_card",
            "main_tabs",
            "conclusion_card",
            "actions_divider",
            "actions_title",
            "actions_row"
          ]
        },
        {
          "id": "title",
          "type": "Text",
          "properties": {
            "text": "FY2023 Quarterly Revenue Analysis",
            "style": "heading"
          }
        },
        {
          "id": "assumptions_card",
          "type": "Card",
          "children": [
            "assumptions_col"
          ]
        },
        {
          "id": "assumptions_col",
          "type": "Column",
          "properties": {
            "spacing": "small"
          },
          "children": [
            "assumptions_title",
            "assumptions_list"
          ]
        },
        {
          "id": "assumptions_title",
          "type": "Text",
          "properties": {
            "text": "Assumptions",
            "style": "subheading",
            "weight": "bold"
          }
        },
        {
          "id": "assumptions_list",
          "type": "List",
          "properties": {
            "spacing": "xsmall"
          },
          "children": [
            "assumption_1",
            "assumption_2"
          ]
        },
        {
          "id": "assumption_1",
          "type": "Text",
          "properties": {
            "text": "All monetary values are in thousands of US Dollars (e.g., 45k = $45,000)."
          }
        },
        {
          "id": "assumption_2",
          "type": "Text",
          "properties": {
            "text": "The quarters are sequential for the purpose of calculating growth (Q1 -> Q2 -> Q3 -> Q4)."
          }
        },
        {
          "id": "summary_card",
          "type": "Card",
          "children": [
            "summary_col"
          ]
        },
        {
          "id": "summary_col",
          "type": "Column",
          "properties": {
            "spacing": "small"
          },
          "children": [
            "summary_title",
            "summary_text"
          ]
        },
        {
          "id": "summary_title",
          "type": "Text",
          "properties": {
            "text": "Summary",
            "style": "subheading",
            "weight": "bold"
          }
        },
        {
          "id": "summary_text",
          "type": "Text",
          "properties": {
            "text": "The fourth quarter (Q4) of FY2023 had the highest total revenue growth, with an increase of $18,000 over the third quarter (Q3). Software consistently remained the highest-earning product line throughout the year, showing strong and steady growth each quarter."
          }
        },
        {
          "id": "main_tabs",
          "type": "Tabs",
          "children": [
            "tab_breakdown",
            "tab_chart",
            "tab_growth"
          ]
        },
        {
          "id": "tab_breakdown",
          "type": "Tab",
          "properties": {
            "label": "Revenue Breakdown"
          },
          "children": [
            "breakdown_table"
          ]
        },
        {
          "id": "breakdown_table",
          "type": "Table",
          "properties": {
            "columns": [
              {
                "header": "Quarter",
                "value": "@{item.quarter}"
              },
              {
                "header": "Software",
                "value": "@{item.software}",
                "horizontalAlignment": "end"
              },
              {
                "header": "Hardware",
                "value": "@{item.hardware}",
                "horizontalAlignment": "end"
              },
              {
                "header": "Services",
                "value": "@{item.services}",
                "horizontalAlignment": "end"
              },
              {
                "header": "Total Revenue",
                "value": "@{item.total}",
                "horizontalAlignment": "end"
              }
            ]
          },
          "bind": {
            "items": "@{data.revenue_breakdown}"
          }
        },
        {
          "id": "tab_chart",
          "type": "Tab",
          "properties": {
            "label": "Chart"
          },
          "children": [
            "revenue_chart"
          ]
        },
        {
          "id": "revenue_chart",
          "type": "Chart",
          "properties": {
            "chartType": "bar",
            "barGrouping": "grouped",
            "title": "FY2023 Quarterly Revenue by Product Line",
            "xAxisLabel": "Fiscal Quarter",
            "yAxisLabel": "Revenue (in thousands USD)",
            "categories": [
              "Q1 2023",
              "Q2 2023",
              "Q3 2023",
              "Q4 2023"
            ],
            "series": [
              {
                "name": "Software",
                "color": "#4A90E2",
                "data": [
                  45,
                  48,
                  52,
                  60
                ]
              },
              {
                "name": "Hardware",
                "color": "#F5A623",
                "data": [
                  30,
                  28,
                  35,
                  40
                ]
              },
              {
                "name": "Services",
                "color": "#7ED321",
                "data": [
                  20,
                  22,
                  25,
                  30
                ]
              }
            ]
          }
        },
        {
          "id": "tab_growth",
          "type": "Tab",
          "properties": {
            "label": "Growth Analysis"
          },
          "children": [
            "growth_table"
          ]
        },
        {
          "id": "growth_table",
          "type": "Table",
          "properties": {
            "columns": [
              {
                "header": "Period",
                "value": "@{item.period}"
              },
              {
                "header": "Total Revenue",
                "value": "@{item.revenue}",
                "horizontalAlignment": "end"
              },
              {
                "header": "Quarter-over-Quarter Growth",
                "value": "@{item.growth}",
                "horizontalAlignment": "end"
              }
            ]
          },
          "bind": {
            "items": "@{data.growth_analysis}"
          }
        },
        {
          "id": "conclusion_card",
          "type": "Card",
          "children": [
            "conclusion_col"
          ]
        },
        {
          "id": "conclusion_col",
          "type": "Column",
          "properties": {
            "spacing": "small"
          },
          "children": [
            "conclusion_title",
            "conclusion_text"
          ]
        },
        {
          "id": "conclusion_title",
          "type": "Text",
          "properties": {
            "text": "Conclusion",
            "style": "subheading",
            "weight": "bold"
          }
        },
        {
          "id": "conclusion_text",
          "type": "Text",
          "properties": {
            "text": "The analysis confirms that the growth from **Q3 to Q4 was the highest** for the fiscal year, both in absolute terms (+$18k) and percentage terms (+16.1%)."
          }
        },
        {
          "id": "actions_divider",
          "type": "Divider"
        },
        {
          "id": "actions_title",
          "type": "Text",
          "properties": {
            "text": "Quick Actions",
            "style": "subheading"
          }
        },
        {
          "id": "actions_row",
          "type": "Row",
          "properties": {
            "spacing": "medium"
          },
          "children": [
            "action_button_1",
            "action_button_2",
            "action_button_3"
          ]
        },
        {
          "id": "action_button_1",
          "type": "Button",
          "properties": {
            "label": "Export Full Data as CSV",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "parameters": {
                "url": "https://example.com/export?format=csv"
              }
            }
          }
        },
        {
          "id": "action_button_2",
          "type": "Button",
          "properties": {
            "label": "Create Q1 2024 Forecast",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "parameters": {
                "url": "https://example.com/forecast?q=q1_2024"
              }
            }
          }
        },
        {
          "id": "action_button_3",
          "type": "Button",
          "properties": {
            "label": "View Product Line Profitability Report",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "parameters": {
                "url": "https://example.com/reports/profitability"
              }
            }
          }
        }
      ]
    }
  }
]
